export const toolDraftSchema = z
  .record(z.string().max(20000), z.unknown())
  .superRefine((drafts, ctx) => {
    if (Object.keys(drafts).length > 3000 || JSON.stringify(drafts).length > 16000000) {
      ctx.addIssue({ code: 'custom', message: 'Too many tool drafts' });
      return;
    }
    for (const [key, value] of Object.entries(drafts)) {
      const schema = fields[key.split(':')[0]];
      if (!schema || !schema.safeParse(value).success)
        ctx.addIssue({ code: 'custom', path: [key], message: 'Invalid tool draft' });
    }
  });
